/**
 * Images every .pkpass must carry (Wallet refuses a pass without icon.png).
 * Resized from public/icon-192.png and embedded as base64 so they ship inside the
 * serverless bundle with no file-tracing configuration.
 */
export const APPLE_PASS_IMAGES: Record<string, string> = {
  "icon.png": "",
  "icon@2x.png": "",
  "icon@3x.png": "",
  "logo.png": "",
  "logo@2x.png": "",
  "logo@3x.png": "",
};

export function applePassImageBuffers(): Record<string, Buffer> {
  return Object.fromEntries(Object.entries(APPLE_PASS_IMAGES).map(([name, b64]) => [name, Buffer.from(b64, "base64")]));
}
